      // 否则 iPad 残留的系统 callout 仍会毁掉一次有效长按。
      if (cancelled && s.mode === 'rate' && s.active) cancelled = false;
      this.session = null;
      [s.holdTimer, s.lockTimer].forEach(t => { if (t) clearTimeout(t); });
      if (s.tickTimer) { clearInterval(s.tickTimer); s.tickTimer = null; }
