    const d = {
      host: location.hostname || (String(location.href).match(/\/\/(?:www\.)?([^/]+)/) || [])[1] || '?',
      bili_jct: has('bili_jct'), SESSDATA: has('SESSDATA'), DedeUserID: has('DedeUserID'),
      nav: '查询中…'
    };
