  const DISLIKE_ITEM_WORDS = ['不感兴趣', '不感興趣', '興味なし', 'Not interested',
    'No me interesa', 'Pas intéressé', 'Не интересно', '관심 없음'];
  function bewDislikeMenuItem() {
    try {
      const items = deepFind('li.context-menu-item, [class*="context-menu-item"]');
      for (let i = 0; i < items.length; i++) {
        const t = String(items[i].textContent || '').trim();
        if (t && DISLIKE_ITEM_WORDS.some(w => t.indexOf(w) >= 0)) return items[i];
      }
      return items[0] || null;   /* 结构兜底：菜单第一项通常就是「不感兴趣」 */
    } catch (e) { return null; }
  }
