    try {
      const f = window.__IBILI_FETCH_BRIDGE__, x = window.__IBILI_XHR_BRIDGE__;
      const hit = u => /\/x\/feed\/dislike/i.test(String(u || ''));
      if (f && Array.isArray(f.last) && f.last.some(e => hit(e.url))) return true;
      if (f && Array.isArray(f.last) && f.last.some(e => /\/history\/toview\/add/i.test(String(e.url || '')))) return false;
      if (x && x.last && hit(x.last.url)) return true;
    } catch (e) {}
