        lab.appendChild(h('div', 'd', t('ui_spm_note')));
        const ctl = h('div', 'ctl');
        ctl.appendChild(spmToggle('useSearchPageModeOnHomePage', 'ui_spm_on', 'ui_spm_off'));
        line.appendChild(lab); line.appendChild(ctl);
        c.appendChild(line);
        out.push(c);
